package org.opensourcepingpong.membership;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="membership_applications") public class MembershipApplication { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(name="real_name") private String realName; @Column(name="student_number") private String studentNumber; private String college,major,grade,phone,reason; @Enumerated(EnumType.STRING) private ApplicationStatus status; @Column(name="reviewer_user_id") private UUID reviewerUserId; @Column(name="review_comment") private String reviewComment; @Column(name="reviewed_at") private Instant reviewedAt; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected MembershipApplication(){} public MembershipApplication(UUID userId,String realName,String studentNumber,String college,String major,String grade,String phone,String reason){id=UUID.randomUUID();this.userId=userId;this.realName=realName;this.studentNumber=studentNumber;this.college=college;this.major=major;this.grade=grade;this.phone=phone;this.reason=reason;status=ApplicationStatus.PENDING;createdAt=Instant.now();updatedAt=createdAt;} public UUID getId(){return id;} public UUID getUserId(){return userId;} public ApplicationStatus getStatus(){return status;} public String getRealName(){return realName;} public void review(UUID by,boolean approved,String comment){if(status!=ApplicationStatus.PENDING)throw new IllegalStateException("已审核");status=approved?ApplicationStatus.APPROVED:ApplicationStatus.REJECTED;reviewerUserId=by;reviewComment=comment;reviewedAt=Instant.now();updatedAt=reviewedAt;} }
